const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Polygon([
        [
            [52.0, 25.0],
            [62.0, 25.0],
            [62.0, 30.0],
            [52.0, 30.0],
            [52.0, 25.0]
        ]
    ]);

    const date1_start = '2021-12-13';
    const date1_end = '2021-12-15';
    const date2_start = '2022-01-06';
    const date2_end = '2022-01-08';

    // 2. Data Acquisition & Check
    // Using Sentinel-1 SAR as it's cloud-penetrating, ideal for water detection.
    const get_s1_collection = function(startDate, endDate) {
        return ee.ImageCollection('COPERNICUS/S1_GRD')
            .filterBounds(aoi)
            .filterDate(startDate, endDate)
            .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
            .filter(ee.Filter.eq('instrumentMode', 'IW'))
            .select(['VV']);
    };

    const collection1 = get_s1_collection(date1_start, date1_end);
    const collection2 = get_s1_collection(date2_start, date2_end);

    const size1 = collection1.size().getInfo();
    const size2 = collection2.size().getInfo();

    if (size1 === 0 || size2 === 0) {
        console.log(`Image count for Dec 2021: ${size1}`);
        console.log(`Image count for Jan 2022: ${size2}`);
        console.log("C1: Empty Collection");
        return;
    }

    const image1 = collection1.mosaic().clip(aoi);
    const image2 = collection2.mosaic().clip(aoi);

    // 3. Processing: Identify water using a threshold on VV polarization.
    // Water has low backscatter, appearing dark in SAR images.
    const waterThreshold = -16; // dB
    const water1 = image1.lt(waterThreshold);
    const water2 = image2.lt(waterThreshold);

    // 4. Calculation: Count the number of water pixels.
    const scale = 3000; // Use a coarse scale to avoid timeouts over a large area.

    const count1_result = water1.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
    }).get('VV');

    const count2_result = water2.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
    }).get('VV');

    const water_pixels1 = count1_result.getInfo();
    const water_pixels2 = count2_result.getInfo();

    // 5. Validation & Final Answer
    if (water_pixels1 === null || water_pixels2 === null) {
        console.log(`Water Pixels (Dec 2021): ${water_pixels1}`);
        console.log(`Water Pixels (Jan 2022): ${water_pixels2}`);
        console.log("C3: Calculation Failure");
        return;
    }

    if (water_pixels1 === 0 || water_pixels2 === 0) {
        console.log(`Water Pixels (Dec 2021): ${water_pixels1.toFixed(0)}`);
        console.log(`Water Pixels (Jan 2022): ${water_pixels2.toFixed(0)}`);
        console.log("C2: No Valid Pixels");
        return;
    }

    console.log(`Image count (Dec 2021): ${size1}`);
    console.log(`Image count (Jan 2022): ${size2}`);
    console.log(`Relative Water Extent (Dec 14, 2021): ${water_pixels1.toFixed(0)} pixels`);
    console.log(`Relative Water Extent (Jan 7, 2022): ${water_pixels2.toFixed(0)} pixels`);

    if (water_pixels2 > water_pixels1) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, (err) => reject(err));
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, (err) => reject(err));
        });
        await runAnalysis();
    } catch (e) {
        console.error(`Initialization or Analysis failed: ${e}`);
        console.log("D");
    }
}

initEE();
